package com.mg.fixturecockpitsim;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Locale;
/** AVM-10.4 airport world: realistic RWY27 markings, rubber, lighting, PAPI and stronger ground motion. */
public final class RunwayHudView extends View{
 private final Paint f=new Paint(3),l=new Paint(3);private final Path p=new Path();private volatile float altitudeM,speedMps,route,groundProgress,headingDeg;private volatile boolean onGround,demoMode;private volatile String phase="";private float scroll,runwayMeters;private long last;
 public RunwayHudView(Context c){super(c);setWillNotDraw(false);f.setStyle(Paint.Style.FILL);l.setStyle(Paint.Style.STROKE);l.setStrokeCap(Paint.Cap.ROUND);}
 public void setDemoMode(boolean e){demoMode=e;postInvalidateOnAnimation();}public void setDemoProgress(double s){route=(float)Math.max(0,s);postInvalidateOnAnimation();}public void setGroundProgress(double q,double hdg){groundProgress=(float)Math.max(0,Math.min(1,q));headingDeg=(float)hdg;postInvalidateOnAnimation();}public void setFlightState(double a,double s,boolean g,String ph){altitudeM=(float)Math.max(0,a);speedMps=(float)Math.max(0,s);onGround=g;phase=ph==null?"":ph;postInvalidateOnAnimation();}
 protected void onDraw(Canvas c){super.onDraw(c);long n=System.nanoTime();float dt=last==0?.016f:Math.min(.05f,(n-last)/1e9f);last=n;scroll=(scroll+speedMps*dt*.040f)%1f;if(phase.contains("TAKEOFF")||phase.contains("ROLLOUT"))runwayMeters+=speedMps*dt;if(phase.contains("HANGAR_START")||phase.contains("RUNWAY_HOLD"))runwayMeters=0;int w=getWidth(),h=getHeight();float hz=h*(.46f+.075f*Math.min(1,altitudeM/1300));sky(c,w,h,hz);if(phase.contains("HANGAR")){hangar(c,w,h,hz);return;}airport(c,w,h,hz);if(phase.contains("TAXI")){taxi(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}if(demoMode&&phase.contains("ORBIT")){scenery(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}if(onGround||phase.contains("RUNWAY")||phase.contains("TAKEOFF")||phase.contains("ROTATE")||phase.contains("APPROACH")||phase.contains("FLARE")||phase.contains("ROLLOUT"))runway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();}
 private void sky(Canvas c,int w,int h,float hz){f.setShader(new LinearGradient(0,0,0,hz,new int[]{0xff071827,0xff38677f,0xff9ac0d2},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,hz,f);f.setShader(null);f.setColor(0x20ffffff);for(int i=0;i<6;i++){float x=w*(.03f+i*.18f),y=hz*(.12f+(i%3)*.06f),ww=w*(.13f+(i%2)*.04f);c.drawOval(x,y,x+ww,y+hz*.032f,f);c.drawOval(x+ww*.18f,y-hz*.014f,x+ww*.66f,y+hz*.025f,f);}f.setShader(new LinearGradient(0,hz*.75f,0,hz,0x00ffffff,0x38d8e4e6,Shader.TileMode.CLAMP));c.drawRect(0,hz*.72f,w,hz,f);f.setShader(null);}
 private void hangar(Canvas c,int w,int h,float hz){float q=phase.contains("PARK")?1-groundProgress:groundProgress,cx=w*.5f;f.setShader(new LinearGradient(0,0,0,h,0xff101418,0xff282d31,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,f);f.setShader(null);float top=h*.17f,bot=h*.88f,half=w*(.17f+.10f*Math.min(1,q));outside(c,cx-half,top,cx+half,bot);f.setColor(0xff2e3234);p.reset();p.moveTo(cx-half,bot);p.lineTo(cx+half,bot);p.lineTo(w,h);p.lineTo(0,h);p.close();c.drawPath(p,f);l.setColor(0xffe0bc24);l.setStrokeWidth(4);c.drawLine(cx,bot,cx,h,l);l.setColor(0xff59636a);l.setStrokeWidth(6);for(int i=0;i<7;i++){float t=i/6f,y=lerp(h*.06f,bot,t),lh=lerp(w*.47f,half,t);c.drawLine(cx-lh,y,cx-lh,bot,l);c.drawLine(cx+lh,y,cx+lh,bot,l);c.drawLine(cx-lh,y,cx+lh,y,l);}f.setColor(0xffffe8a2);for(int i=0;i<8;i++){float x=w*(.12f+i*.11f);c.drawRoundRect(x,h*.08f,x+w*.055f,h*.095f,5,5,f);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(18,w*.019f));c.drawText("HANGAR 01   •   APRON   •   RWY 27",w*.035f,h*.92f,f);}
 private void outside(Canvas c,float x0,float y0,float x1,float y1){f.setShader(new LinearGradient(0,y0,0,y1,0xff83b3cc,0xff40583a,Shader.TileMode.CLAMP));c.drawRect(x0,y0,x1,y1,f);f.setShader(null);float cx=(x0+x1)/2;f.setColor(0xff4a4e50);p.reset();p.moveTo(cx-(x1-x0)*.05f,y0+(y1-y0)*.16f);p.lineTo(cx+(x1-x0)*.05f,y0+(y1-y0)*.16f);p.lineTo(x1,y1);p.lineTo(x0,y1);p.close();c.drawPath(p,f);l.setColor(0xffe1c227);l.setStrokeWidth(3);c.drawLine(cx,y0+(y1-y0)*.16f,cx,y1,l);}
 private void taxi(Canvas c,int w,int h,float hz){f.setColor(0xff344735);c.drawRect(0,hz,w,h,f);buildings(c,w,h,hz);float cx=w*.5f,far=w*.045f,near=w*.25f;p.reset();p.moveTo(cx-far,hz+h*.02f);p.lineTo(cx+far,hz+h*.02f);p.lineTo(cx+near,h);p.lineTo(cx-near,h);p.close();f.setColor(0xff454a4c);c.drawPath(p,f);l.setColor(0xffe5c329);l.setStrokeWidth(4);c.drawLine(cx,hz+h*.02f,cx,h,l);for(int i=0;i<18;i++){float z=(i/18f+scroll*.45f)%1f,y=lerp(hz+h*.03f,h,z*z),hh=lerp(far,near,z);f.setColor(0xff438cff);c.drawCircle(cx-hh,y,2+3*z,f);c.drawCircle(cx+hh,y,2+3*z,f);}f.setColor(0xddffffff);f.setTextSize(Math.max(14,w*.015f));c.drawText("HDG "+String.format(Locale.US,"%03.0f",norm(headingDeg))+"  •  RWY 27",w*.04f,h*.92f,f);}
 private void runway(Canvas c,int w,int h,float hz){float near=1-Math.min(1,altitudeM/1050f),err=angleError(headingDeg,270f);float cx=w*.5f+clamp(err/28f,-1,1)*w*.12f,fh=w*(.017f+.012f*near),nh=w*(onGround?.45f:(.12f+.30f*near)),fy=hz+h*.014f,ny=h*(onGround?.999f:(.72f+.26f*near));terrain(c,w,h,hz);
  // shoulders + asphalt perspective
  quad(c,cx-fh*1.28f,fy,cx+fh*1.28f,fy,cx+nh*1.10f,ny,cx-nh*1.10f,ny,0xff6a6d6b);quad(c,cx-fh,fy,cx+fh,fy,cx+nh,ny,cx-nh,ny,0xff25292b);
  // subtle asphalt aggregate / longitudinal tyre wear
  for(int i=-8;i<=8;i++){float a=i/8f;l.setColor(i%3==0?0x33484a4b:0x1d0e0f10);l.setStrokeWidth(1+Math.abs(a)*1.2f);c.drawLine(cx+fh*a*.82f,fy,cx+nh*a*.82f,ny,l);}l.setColor(0xfff4f3ed);l.setStrokeWidth(Math.max(2,w*.0025f));c.drawLine(cx-fh,fy,cx-nh,ny,l);c.drawLine(cx+fh,fy,cx+nh,ny,l);
  // runway centerline: perspective-correct moving 30 m style segments
  for(int i=0;i<34;i++){float q=(i/34f+scroll)%1f,z=q*q,y=lerp(fy,ny,z),y2=Math.min(ny,y+4+44*z);l.setColor(0xfff5f5f0);l.setStrokeWidth(2+12*z);c.drawLine(cx,y,cx,y2,l);}
  // edge lights and distance motion cues
  for(int i=0;i<30;i++){float q=(i/30f+scroll*.62f)%1f,z=q*q,y=lerp(fy,ny,z),hh=lerp(fh,nh,z);f.setColor(i>25?0xffffd56b:0xfff3f0d8);float r=1+4*z;c.drawCircle(cx-hh,y,r,f);c.drawCircle(cx+hh,y,r,f);}
  // touchdown-zone bars and aiming-point blocks
  for(int set=0;set<3;set++){float base=(.31f+set*.17f+scroll*.16f)%1f,z=base*base,y=lerp(fy,ny,z),hh=lerp(fh,nh,z),bw=hh*.10f,bh=5+20*z;f.setColor(0xffeeeeea);for(int s=-1;s<=1;s+=2){c.drawRect(cx+s*hh*.43f-bw,y,cx+s*hh*.43f+bw,y+bh,f);c.drawRect(cx+s*hh*.66f-bw*.72f,y,cx+s*hh*.66f+bw*.72f,y+bh,f);}}
  float ap=(.46f+scroll*.11f)%1f,az=ap*ap,ay=lerp(fy,ny,az),ah=lerp(fh,nh,az);f.setColor(0xfff4f4ef);c.drawRect(cx-ah*.62f,ay,cx-ah*.38f,ay+12+32*az,f);c.drawRect(cx+ah*.38f,ay,cx+ah*.62f,ay+12+32*az,f);
  // threshold piano keys + RWY 27 designation moves with actual ground distance
  float takeDist=phase.contains("TAKEOFF")?runwayMeters:0,nz=.49f+takeDist/300f;if(nz<=1.04f){float z=clamp(nz,0,1),y=lerp(fy,ny,z*z),hh=lerp(fh,nh,z);f.setColor(0xfffafaf5);for(int i=-5;i<=5;i++){if(i==0)continue;float x=cx+i*hh*.095f;c.drawRect(x-hh*.030f,y,x+hh*.030f,y+13+38*z,f);}f.setTextAlign(Paint.Align.CENTER);f.setTextSize(Math.max(27,w*(.033f+.030f*z)));c.drawText("27",cx,y+58+42*z,f);f.setTextAlign(Paint.Align.LEFT);}
  // PAPI on left: 2 white / 2 red on nominal final
  if(!onGround||phase.contains("APPROACH")||phase.contains("FLARE")){float py=lerp(fy,ny,.36f),ph=lerp(fh,nh,.36f);for(int i=0;i<4;i++){f.setColor(i<2?0xffffffff:0xffff3b30);c.drawCircle(cx-ph*1.28f+i*6,py,3.2f,f);}}
  // runway remaining signs and guard lights
  if(onGround){for(int i=0;i<5;i++){float q=(i/5f+scroll*.28f)%1f,z=q*q,y=lerp(fy,ny,z),hh=lerp(fh,nh,z);f.setColor(0xff111513);c.drawRect(cx+hh*1.06f,y-5,cx+hh*1.06f+12+8*z,y+8+7*z,f);f.setColor(0xffffffff);f.setTextSize(7+8*z);c.drawText(String.valueOf(5-i),cx+hh*1.07f,y+6,f);}}
  if(phase.contains("APPROACH")||phase.contains("FLARE")){f.setColor(Math.abs(err)<2.5?0xff7fe889:0xffffd35a);f.setTextSize(Math.max(14,w*.015f));c.drawText(Math.abs(err)<2.5?"RWY 27 • CENTERLINE CAPTURED":"RWY 27 • ALIGNING",w*.68f,h*.92f,f);}}
 private void quad(Canvas c,float x1,float y1,float x2,float y2,float x3,float y3,float x4,float y4,int col){p.reset();p.moveTo(x1,y1);p.lineTo(x2,y2);p.lineTo(x3,y3);p.lineTo(x4,y4);p.close();f.setColor(col);c.drawPath(p,f);}
 private void terrain(Canvas c,int w,int h,float hz){f.setColor(0xff304632);c.drawRect(0,hz,w,h,f);mountains(c,w,h,hz,.25f,false);buildings(c,w,h,hz);}
 private void airport(Canvas c,int w,int h,float hz){f.setColor(0xff314331);c.drawRect(0,hz,w,hz+h*.12f,f);buildings(c,w,h,hz);}
 private void buildings(Canvas c,int w,int h,float hz){for(int i=0;i<9;i++){float x=w*(.025f+i*.055f),bw=w*(.033f+(i%2)*.012f),bh=h*(.025f+(i%3)*.015f);f.setColor(i%3==0?0xff72797b:0xff555d60);c.drawRect(x,hz-bh,x+bw,hz,f);f.setColor(0x66d9ecff);for(int k=0;k<3;k++)c.drawRect(x+bw*.16f+k*bw*.24f,hz-bh*.72f,x+bw*.27f+k*bw*.24f,hz-bh*.54f,f);}float tx=w*.82f;f.setColor(0xff50595d);c.drawRect(tx-5,hz-h*.09f,tx+5,hz,f);c.drawRect(tx-18,hz-h*.103f,tx+18,hz-h*.083f,f);f.setColor(0xff20272a);c.drawRect(tx-13,hz-h*.101f,tx+13,hz-h*.087f,f);}
 private void scenery(Canvas c,int w,int h,float hz){float t=Math.min(300,route);if(t<45){coast(c,w,h,hz,.30f);label(c,w,h,"SAHİL ÜZERİ TIRMANIŞ");}else if(t<95){mountains(c,w,h,hz,.58f,false);label(c,w,h,"DAĞLARA YAKLAŞMA");}else if(t<150){mountains(c,w,h,hz,.82f,true);label(c,w,h,"VADİ İÇİ UÇUŞ");}else if(t<210){mountains(c,w,h,hz,.96f,true);road(c,w,h,hz);label(c,w,h,"DAĞ YOLU TAKİBİ");}else if(t<255){lake(c,w,h,hz);label(c,w,h,"GÖL / KIYI GEÇİŞİ");}else if(t<280){mountains(c,w,h,hz,.75f,false);label(c,w,h,"YÜKSEK ARAZİ");}else{mountains(c,w,h,hz,.34f,false);airport(c,w,h,hz);label(c,w,h,"RWY 27 İÇİN HİZALANMA");}}
 private void label(Canvas c,int w,int h,String s){f.setColor(0xe8ffffff);f.setTextSize(Math.max(19,w*.020f));c.drawText(s,w*.04f,h*.89f,f);}
 private void mountains(Canvas c,int w,int h,float hz,float scale,boolean valley){mountainLayer(c,w,h,hz,scale*.55f,0xff768786,1.12f,valley);mountainLayer(c,w,h,hz,scale*.76f,0xff526961,1.38f,valley);mountainLayer(c,w,h,hz,scale,0xff30483d,1.67f,valley);}
 private void mountainLayer(Canvas c,int w,int h,float hz,float scale,int col,float freq,boolean valley){p.reset();p.moveTo(0,h);for(int i=0;i<=22;i++){float x=w*i/22f,y=hz-h*scale*(.035f+.13f*(float)Math.abs(Math.sin(i*freq+route*.010)));if(valley&&i>9&&i<13)y+=h*.12f;p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(col);c.drawPath(p,f);}
 private void coast(Canvas c,int w,int h,float hz,float s){mountains(c,w,h,hz,s,false);water(c,w,h,hz+h*.07f);}private void lake(Canvas c,int w,int h,float hz){mountains(c,w,h,hz,.56f,true);water(c,w,h,hz+h*.12f);}
 private void water(Canvas c,int w,int h,float top){f.setShader(new LinearGradient(0,top,0,h,0xff4388a4,0xff082b42,Shader.TileMode.CLAMP));c.drawRect(0,top,w,h,f);f.setShader(null);for(int i=0;i<34;i++){float x=(i*101+route*9)%Math.max(1,w),y=top+(h-top)*(.08f+((i*31)%82)/100f);f.setColor(i%4==0?0x45ffffff:0x228fd0e4);c.drawOval(x,y,x+14+i%26,y+2+i%2,f);}}
 private void road(Canvas c,int w,int h,float hz){l.setColor(0xff6f7472);l.setStrokeWidth(Math.max(12,w*.018f));p.reset();p.moveTo(w*.10f,h);p.cubicTo(w*.38f,h*.72f,w*.32f,h*.60f,w*.61f,hz+h*.06f);c.drawPath(p,l);l.setColor(0xffe8d15a);l.setStrokeWidth(2);c.drawPath(p,l);}
 private static float norm(float a){a%=360;if(a<0)a+=360;return a;}private static float angleError(float h,float t){float d=t-h;while(d>180)d-=360;while(d<-180)d+=360;return d;}private static float clamp(float v,float lo,float hi){return Math.max(lo,Math.min(hi,v));}private static float lerp(float a,float b,float t){return a+(b-a)*t;}
}
